@Override
        public @Nullable InfectionStatus read(IAttachmentHolder holder, RegistryFriendlyByteBuf buf, @Nullable InfectionStatus previousValue) {
            int totalTicks = buf.readInt();
            if (holder instanceof LivingEntity entity) {
                return new InfectionStatus(entity, totalTicks);
            }
            return previousValue;
        }

@Override
        public @NotNull WerewolfPlayer read(@NotNull IAttachmentHolder holder, @NotNull CompoundTag tag, HolderLookup.Provider provider) {
            if(holder instanceof Player player) {
                var werewolf = new WerewolfPlayer(player);
                werewolf.deserializeNBT(provider, tag);
                return werewolf;
            }
            throw new IllegalArgumentException("Expected Player, got " + holder.getClass().getSimpleName());
        }

@Override
	public void readAdditionalSaveData(ValueInput compound) {
		super.readAdditionalSaveData(compound);
		this.setColorFlags(compound.getIntOr("ColorFlags", 0));
		this.setRewarded(compound.getBooleanOr("Rewarded", false));
		this.loadHomePointFromNbt(compound);
	}

@Override
	public void readNBT(Capability<IManaCapability> capability, IManaCapability instance, EnumFacing side, NBTBase nbt) {
		NBTTagCompound tag = (NBTTagCompound) nbt;

		instance.setMaxMana(tag.getDouble(MAX_MANA));
		instance.setMaxBurnout(tag.getDouble(MAX_BURNOUT));
		instance.setMana(tag.getDouble(MANA));
		instance.setBurnout(tag.getDouble(BURNOUT));
		if (tag.hasKey(BLOOD_TYPE))
			instance.setBloodType(EnumBloodType.getType(tag.getString(BLOOD_TYPE)));
	}

@Override
	public void readNBT(Capability<IMiscCapability> capability, IMiscCapability instance, EnumFacing side, NBTBase nbt) {
		NBTTagCompound tag = (NBTTagCompound) nbt;

		if (tag.hasUniqueId("fairy_selected")) {
			instance.setSelectedFairy(NBTHelper.getUniqueId(tag, "fairy_selected"));
		} else instance.setSelectedFairy(null);
	}

@Override
    public MagicData read(IAttachmentHolder holder, CompoundTag tag, HolderLookup.Provider provider) {
        //Entities implement IIAttachmentHolder
        var magicData = holder instanceof ServerPlayer serverPlayer ? new MagicData(serverPlayer) : new MagicData(true);
        magicData.loadNBTData(tag, provider);
        return magicData;
    }
